-- v8.5.1 heartbeat schema hotfix\n-- Safe to run more than once.\n\n-- 1) Required heartbeat columns.\nalter table public.translation_jobs\n  add column if not exists client_heartbeat_at timestamptz not null default now();\n\nalter table public.translation_jobs\n  add column if not exists client_active boolean not null default true;\n\nalter table public.translation_jobs\n  add column if not exists paused_at timestamptz;\n\n-- Make existing rows usable immediately.\nupdate public.translation_jobs\nset\n  client_heartbeat_at = coalesce(client_heartbeat_at, now()),\n  client_active = coalesce(client_active, true)\nwhere client_heartbeat_at is null\n   or client_active is null;\n\n-- 2) Browser heartbeat/resume RPC.\ncreate or replace function public.pdf_translation_client_signal(\n  p_job_id uuid,\n  p_action text default 'heartbeat'\n)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_client_user_id uuid;\n  v_owner uuid;\n  v_status text;\n  v_action text;\nbegin\n  v_client_user_id := auth.uid();\n  if v_client_user_id is null then\n    raise exception 'authentication required';\n  end if;\n\n  v_action := lower(coalesce(p_action, 'heartbeat'));\n\n  select user_id, status\n    into v_owner, v_status\n  from public.translation_jobs\n  where id = p_job_id;\n\n  if v_owner is null or v_owner <> v_client_user_id then\n    raise exception 'job not found';\n  end if;\n\n  if v_action in ('heartbeat', 'resume') then\n    update public.translation_jobs\n    set\n      client_heartbeat_at = now(),\n      client_active = true\n    where id = p_job_id;\n\n    if v_status = 'paused' then\n      update public.translation_jobs\n      set\n        status = 'queued',\n        paused_at = null,\n        started_at = null,\n        finished_at = null,\n        error = null,\n        progress_message =\n          '연결이 복구되어 저장된 진행 지점부터 이어서 진행합니다.',\n        progress_updated_at = now(),\n        dispatch_last_at = null\n      where id = p_job_id;\n\n      -- Dispatch only if the v8.x dispatch function is already installed.\n      if to_regprocedure(\n           'public.dispatch_pdf_translation_worker(uuid,text)'\n         ) is not null then\n        perform public.dispatch_pdf_translation_worker(\n          p_job_id,\n          'client-resume'\n        );\n      end if;\n\n      return 'queued';\n    end if;\n\n    return v_status;\n  end if;\n\n  if v_action = 'disconnect' then\n    update public.translation_jobs\n    set client_active = false\n    where id = p_job_id;\n    return v_status;\n  end if;\n\n  raise exception 'unsupported client signal';\nend;\n$$;\n\nrevoke all on function public.pdf_translation_client_signal(uuid, text)\nfrom public;\ngrant execute on function public.pdf_translation_client_signal(uuid, text)\nto authenticated;\n\n-- 3) Ask PostgREST/Supabase API to refresh its schema cache immediately.\nnotify pgrst, 'reload schema';\n\n-- 4) Verification. Expected: all three columns plus the RPC are present.\nselect\n  column_name,\n  data_type\nfrom information_schema.columns\nwhere table_schema = 'public'\n  and table_name = 'translation_jobs'\n  and column_name in (\n    'client_heartbeat_at',\n    'client_active',\n    'paused_at'\n  )\norder by column_name;\n\nselect\n  to_regprocedure(\n    'public.pdf_translation_client_signal(uuid,text)'\n  ) as heartbeat_rpc;\n